internal sealed class FloatingTextSettingsPane:Grid {
 readonly EnergyOverlay owner;readonly Window window;readonly StackPanel controls=new StackPanel();readonly CheckBox enabled=new CheckBox(),channelEnabled=new CheckBox();readonly Button[] tabs=new Button[3];readonly Image preview=new Image{Height=180,Stretch=Stretch.Uniform};readonly Button test;
 readonly List<Action<FloatingTextStyle>> reloaders=new List<Action<FloatingTextStyle>>();readonly DispatcherTimer timer=new DispatcherTimer();readonly System.Diagnostics.Stopwatch clock=System.Diagnostics.Stopwatch.StartNew();readonly ComboBox direction=new ComboBox{Width=170,Height=34};readonly TextBlock hint=SettingsVisual.Text("",11,"#929CAD");Bitmap glyph;FloatingTextOptions shown;string language;int selected;bool loading,released;
 internal FloatingTextSettingsPane(EnergyOverlay owner,Window window){this.owner=owner;this.window=window;var scroll=new ScrollViewer{Content=controls,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};scroll.SetResourceReference(FrameworkElement.StyleProperty,"SlimScroll");Children.Add(scroll);
  var row=Row("Enable floating combat text");Grid.SetColumn(enabled,1);row.Children.Add(enabled);controls.Children.Add(row);enabled.Click+=delegate{if(loading)return;var c=owner.Configuration;c.FloatingText.Enabled=enabled.IsChecked==true;owner.ApplyConfiguration(c);};
  var nav=new Grid{Margin=new Thickness(0,18,0,6)};controls.Children.Add(nav);for(int i=0;i<3;i++){int index=i;nav.ColumnDefinitions.Add(new ColumnDefinition());tabs[i]=SettingsVisual.Button(FloatingTextOptions.Name(i),delegate{Select(index);});tabs[i].Padding=new Thickness(4,11,4,11);tabs[i].Margin=new Thickness(i==0?0:4,0,i==2?0:4,0);Grid.SetColumn(tabs[i],i);nav.Children.Add(tabs[i]);}
  var group=Group("PREVIEW");group.Children.Add(preview);group.Children.Add(SettingsVisual.Text("Simulated numbers · critical hits end in !!",11,"#929CAD"));test=SettingsVisual.Button("Test floating text",delegate{owner.FloatingText.ToggleTest(selected);ReloadTest();});test.Margin=new Thickness(0,12,0,0);group.Children.Add(test);
  group=Group("BEHAVIOR");row=Row("Show this category");Grid.SetColumn(channelEnabled,1);row.Children.Add(channelEnabled);group.Children.Add(row);channelEnabled.Click+=delegate{Change(o=>o.Enabled=channelEnabled.IsChecked==true);};
  row=Row("Movement direction");direction.Items.Add("Up");direction.Items.Add("Down");Grid.SetColumn(direction,1);row.Children.Add(direction);group.Children.Add(row);direction.SelectionChanged+=delegate{if(!loading)Change(o=>o.Up=direction.SelectedIndex==0);};
  Number(group,"Time on screen","s",.4M,6,2,.05M,o=>(decimal)o.Duration,(o,v)=>o.Duration=(double)v);
  Number(group,"Travel distance","px",0,400,0,5,o=>o.Travel,(o,v)=>o.Travel=(int)v);Number(group,"Horizontal spread","%",0,160,0,5,o=>o.Spread,(o,v)=>o.Spread=(int)v);Number(group,"Vertical spacing","px",0,40,0,1,o=>o.Spacing,(o,v)=>o.Spacing=(int)v);
  group=Group("APPEARANCE");Number(group,"Text size","px",12,64,0,1,o=>o.FontSize,(o,v)=>o.FontSize=(int)v);Number(group,"Text scale","%",50,200,0,5,o=>o.Scale,(o,v)=>o.Scale=(int)v);Number(group,"Text opacity","%",0,100,0,1,o=>o.Opacity,(o,v)=>o.Opacity=(int)v);PickColor(group,"Text color",o=>o.Color,(o,v)=>o.Color=v);PickColor(group,"Outline color",o=>o.OutlineColor,(o,v)=>o.OutlineColor=v);Number(group,"Outline thickness","px",0,6,0,1,o=>o.OutlineWidth,(o,v)=>o.OutlineWidth=(int)v);
  group=Group("POSITION");Number(group,"Spawn position X","px",-100000,100000,0,1,o=>o.X,(o,v)=>o.X=(int)v);Number(group,"Spawn position Y","px",-100000,100000,0,1,o=>o.Y,(o,v)=>o.Y=(int)v);group.Children.Add(SettingsVisual.Text("Unlock widgets in General to drag each category. Drag its lower-right corner to scale it. Numbers appear at the anchor and move in the chosen direction.",11,"#929CAD"));
  hint.Margin=new Thickness(2,4,2,16);controls.Children.Add(hint);timer.Interval=TimeSpan.FromMilliseconds(33);timer.Tick+=delegate{if(IsVisible&&!released&&window.IsActive&&window.WindowState!=WindowState.Minimized){PaintPreview();ReloadTest();}};window.Activated+=ActivatePreview;window.Deactivated+=PausePreview;IsVisibleChanged+=delegate{if(IsVisible&&!released&&window.IsActive)timer.Start();else{timer.Stop();owner.FloatingText.StopTest();}};Reload();
 }
 void ActivatePreview(object sender,EventArgs e){if(IsVisible&&!released)timer.Start();}
 void PausePreview(object sender,EventArgs e){timer.Stop();}
 Grid Row(string label){var row=new Grid{MinHeight=38,Margin=new Thickness(0,5,0,5)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(SettingsVisual.Text(label));return row;}
 StackPanel Group(string title){var head=SettingsVisual.Text(title,10,"#929CAD");head.Margin=new Thickness(2,23,0,9);controls.Children.Add(head);var group=new StackPanel();var card=SettingsVisual.Card(group,new Thickness(17,12,17,12));controls.Children.Add(card);return group;}
 void Change(Action<FloatingTextStyle> edit){if(loading)return;var c=owner.Configuration;edit(c.FloatingText.Style(selected));c.FloatingText.Normalize();owner.ApplyConfiguration(c);}
 void Number(StackPanel group,string label,string unit,decimal min,decimal max,int precision,decimal step,Func<FloatingTextStyle,decimal> read,Action<FloatingTextStyle,decimal> write){var row=Row(label);var holder=new StackPanel{Orientation=Orientation.Horizontal};var number=new SettingsNumber(label,min,max,precision,step);holder.Children.Add(number);var suffix=SettingsVisual.Text(unit,11,"#929CAD");suffix.Margin=new Thickness(8,0,0,0);holder.Children.Add(suffix);Grid.SetColumn(holder,1);row.Children.Add(holder);group.Children.Add(row);number.Changed+=delegate{Change(o=>write(o,number.Value));};reloaders.Add(o=>number.Value=read(o));}
 void PickColor(StackPanel group,string label,Func<FloatingTextStyle,string> read,Action<FloatingTextStyle,string> write){var row=Row(label);Button button=null;button=SettingsVisual.Button("",delegate{var picker=new HelperColorPicker(read(owner.Configuration.FloatingText.Style(selected)),label,owner.Language){Owner=window};if(picker.ShowDialog()==true)Change(o=>write(o,picker.SelectedHex));});button.MinWidth=130;Grid.SetColumn(button,1);row.Children.Add(button);group.Children.Add(row);reloaders.Add(o=>{button.Content=read(o);button.Foreground=SettingsVisual.Brush(read(o));});}
 internal void Select(int index){if(index<0||index>2)return;if(selected!=index)owner.FloatingText.StopTest();selected=index;shown=null;Reload();}
 void ReloadTest(){test.Content=UiLanguage.Text(owner.FloatingText.Testing?"Stop test":"Test floating text",owner.Language);}
 internal void Reload(){if(released)return;ReloadTest();var cfg=owner.Configuration.FloatingText;if(shown!=null&&FloatingTextOptions.Same(shown,cfg)&&language==owner.Language)return;loading=true;try{enabled.IsChecked=cfg.Enabled;var style=cfg.Style(selected);channelEnabled.IsChecked=style.Enabled;direction.Items[0]=UiLanguage.Text("Up",owner.Language);direction.Items[1]=UiLanguage.Text("Down",owner.Language);direction.SelectedIndex=style.Up?0:1;foreach(var reload in reloaders)reload(style);for(int i=0;i<3;i++){tabs[i].Background=SettingsVisual.Brush(i==selected?"#235DC7B0":"#0CFFFFFF");tabs[i].Foreground=SettingsVisual.Brush(i==selected?"#A7E5D5":"#929CAD");}if(glyph!=null)glyph.Dispose();var sample=style.Copy();glyph=FloatingTextMotion.Glyph(FloatingTextMotion.Number(selected==0?12480u:selected==1?2180u:4360u,selected,true),sample);hint.Text=UiLanguage.Text("Only supported received impacts are shown. Healing values may include overhealing. Unknown critical flags do not add !!.",owner.Language);shown=cfg.Copy();language=owner.Language;PaintPreview();UiLanguage.Apply(this,language);}finally{loading=false;}}
 void PaintPreview(){if(glyph==null)return;var o=owner.Configuration.FloatingText.Style(selected).Copy();double age=clock.Elapsed.TotalSeconds%(o.Duration+.35);o.Travel=Math.Min(95,o.Travel*o.Scale/100);o.Scale=100;using(var frame=new Bitmap(620,180,PixelFormat.Format32bppPArgb))using(var g=Graphics.FromImage(frame))using(var attributes=new ImageAttributes()){
   g.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(Color.FromArgb(35,135,155,170))){pen.DashStyle=DashStyle.Dot;g.DrawLine(pen,310,20,310,160);}float y=o.Up?135:35;FloatingTextMotion.Sprite(g,glyph,310-glyph.Width/2f,y-glyph.Height/2+FloatingTextMotion.Offset(age,o),FloatingTextMotion.Alpha(age,o.Duration)*o.Opacity/100,attributes,new ColorMatrix());preview.Source=SettingsVisual.Bitmap(frame);
  }}
 internal void Verify(string root){Select(0);SettingsVisual.RenderPreview(window,Path.Combine(root,"designs","floating-text-settings-en.png"));var c=owner.Configuration;c.Language="es";owner.ApplyConfiguration(c);Reload();SettingsVisual.RenderPreview(window,Path.Combine(root,"designs","floating-text-settings-es.png"));if(!UiLanguage.Text("Damage dealt","es").Contains("infligido"))throw new Exception("Floating text categories must be localized");}
 internal void Release(){if(released)return;released=true;timer.Stop();window.Activated-=ActivatePreview;window.Deactivated-=PausePreview;owner.FloatingText.StopTest();preview.Source=null;if(glyph!=null){glyph.Dispose();glyph=null;}}
}
